#include "riscv_test.h"
#include "test_macros.h"

RVTEST_RV64U
RVTEST_CODE_BEGIN

  # Exhaustive physical-mode MUL register-field verification.
  # Covers every ordered (rd, rs1, rs2) assignment from x0 through x31.
  # TESTNUM is written only on failure so x3 can be tested as an operand.

.macro CHECK_MUL_CASE testnum, rd, rs1, rs2, val1, val2, expected, check
mul_random_case_\testnum\():
  li \rs1, \val1
  li \rs2, \val2
  mul \rd, \rs1, \rs2
  li \check, \expected
  beq \rd, \check, 1f
  li TESTNUM, \testnum
  la \check, fail
  jr \check
1:
.endm

